#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>
#include <iostream>

int main() {
    try {
        auto doc = nlohmann::json_document::parse("true");
        auto view = doc.root();
        bool val = view.get<bool>();
        std::cout << "Got bool: " << (val ? "true" : "false") << std::endl;
    } catch (const std::exception& e) {
        std::cout << "Unexpected exception: " << e.what() << std::endl;
    }
    return 0;
}
